346	/// Desperate Ravings draws 2 cards, then discards 1. Net hand size change is +1.
347	#[test]
348	fn desperate_ravings_draws_two_discards_one() {
349	    let reg = registry();
350	    let mut state = game_at_step(Step::PrecombatMain, P0);
351	
352	    // Stock library with 3 cards to draw from.
353	    let mountain_id = reg.get_id_by_name("Mountain").unwrap();
354	    let mut lib_cards = Vec::new();
355	    for _ in 0..3 {
356	        let obj = state.create_object(mountain_id, P0, Zone::Library, None, None);
357	        state.get_object_mut(obj).unwrap().name = "Mountain".into();
358	        lib_cards.push(obj);
359	    }
360	    state.get_player_mut(P0).library_order = lib_cards;
361	
362	    let hand_before = state.objects_in_zone(Zone::Hand, P0).len();
363	
364	    // Cast Desperate Ravings. Cost: {1}{R}.
365	    let dr = castable_spell(&mut state, &reg, "Desperate Ravings", P0);
366	
367	    state = cast_and_resolve(&state, &reg, dr, vec![]);
368	
369	    let hand_after = state.objects_in_zone(Zone::Hand, P0).len();
370	    // Before: hand_before cards + Desperate Ravings (which goes to stack then graveyard).
371	    // The spell is cast from hand (removing it), then draws 2, discards 1 => net +1 from the
372	    // state before casting. But hand_before was measured before we created the spell card.
373	    // So: hand_before (0) -> +1 (create DR) -> -1 (cast DR) -> +2 (draw) -> -1 (discard) = 1
374	    assert_eq!(hand_after, hand_before + 1,
