49	/// Moan of the Unhallowed creates two 2/2 Zombie tokens.
50	#[test]
51	fn moan_creates_two_zombies() {
52	    let reg = registry();
53	    let mut state = game_at_step(Step::PrecombatMain, P0);
54	
55	    let card = castable_spell(&mut state, &reg, "Moan of the Unhallowed", P0);
56	
57	    state = cast_and_resolve(&state, &reg, card, vec![]);
58	
59	    assert_eq!(state.get_object(card).unwrap().zone, Zone::Graveyard);
60	
61	    let tokens: Vec<_> = state.objects_in_zone(Zone::Battlefield, P0)
62	        .into_iter()
63	        .filter(|o| o.is_token && o.name == "Zombie")
64	        .collect();
65	    assert_eq!(tokens.len(), 2, "Should have two Zombie tokens");
66	
